<?php /** @var array<string,mixed> $f */ /** @var list<array<string,mixed>> $rows */ /** @var int $total */ /** @var int $page */ /** @var int $perPage */ /** @var string $status */ /** @var bool $canExport */ use Vertex\Core\View; ?>
<div class="page-head"><div><p class="eyebrow"><a href="/forms/<?= e($f['public_id']) ?>"><?= e($f['title']) ?></a></p><h1>Answers</h1></div><?php if ($canExport) : ?><div class="actions"><a class="btn btn-ghost" href="/forms/<?= e($f['public_id']) ?>/export">Download CSV</a></div><?php endif; ?></div>
<form method="get" class="toolbar"><div class="field"><label for="st">Show</label><select id="st" name="status"><option value="">All</option><?php foreach (['new' => 'New', 'reviewed' => 'Reviewed', 'archived' => 'Archived'] as $k => $l) : ?><option value="<?= e($k) ?>"<?= $status === $k ? ' selected' : '' ?>><?= e($l) ?></option><?php endforeach; ?></select></div><div class="field"><button class="btn btn-ghost" type="submit">Filter</button></div></form>
<?php foreach ($rows as $s) : ?><div class="panel"><div class="page-head"><h2><?= e($s['reference']) ?> <span class="muted"><?= e(local_time($s['created_at'])) ?><?= $s['user_name'] ? ' · ' . e($s['user_name']) : '' ?> · <?= e(ucfirst((string) $s['status'])) ?></span></h2>
    <form method="post" action="/forms/<?= e($f['public_id']) ?>/submissions/<?= e($s['public_id']) ?>" class="inline-form"><?= csrf_field() ?><select name="status" aria-label="Status"><?php foreach (['new' => 'New', 'reviewed' => 'Reviewed', 'archived' => 'Archived'] as $k => $l) : ?><option value="<?= e($k) ?>"<?= $s['status'] === $k ? ' selected' : '' ?>><?= e($l) ?></option><?php endforeach; ?></select><button class="btn btn-ghost btn-sm" type="submit">Set</button></form></div>
    <dl class="detail-list"><?php foreach ($s['answers'] as $a) : ?><dt><?= e($a['label']) ?></dt><dd class="prewrap"><?= e(is_array($a['value']) ? implode(', ', $a['value']) : (string) $a['value']) ?></dd><?php endforeach; ?></dl>
    <?php if ($s['enquiry_id']) : ?><p class="muted">A CRM lead was created from this answer.</p><?php endif; ?></div><?php endforeach; ?>
<?php if ($rows === []) : ?><p class="muted">No answers yet.</p><?php endif; ?>
<?= View::partial('pagination', ['page' => $page, 'perPage' => $perPage, 'total' => $total, 'filters' => array_filter(['status' => $status])]) ?>
